1	<?php
2	declare(strict_types=1);
3	
4	namespace WP_Rocket\Engine\Common\JobManager\Cron;
5	
6	use WP_Rocket\Event_Management\Subscriber_Interface;
7	use WP_Rocket\Engine\Common\Queue\RUCSSQueueRunner;
8	use WP_Rocket\Engine\Common\JobManager\JobProcessor;
9	
10	class Subscriber implements Subscriber_Interface {
11		/**
12		 * JobProcessor instance
13		 *
14		 * @var JobProcessor
15		 */
16		private $job_processor;
17	
18		/**
19		 * Array of Factories.
20		 *
21		 * @var array
22		 */
23		private $factories;
24	
25		/**
26		 * Instantiate the class
27		 *
28		 * @param JobProcessor $job_processor JobProcessor instance.
29		 * @param array        $factories Array of factories.
30		 */
31		public function __construct(
32			JobProcessor $job_processor,
33			array $factories
34		) {
35			$this->job_processor = $job_processor;
36			$this->factories     = $factories;
37		}
38	
39		/**
40		 * Return an array of events that this subscriber listens to.
41		 *
42		 * @return array
43		 */
44		public static function get_subscribed_events(): array {
45			return [
46				'rocket_saas_pending_jobs'          => 'process_pending_jobs',
47				'rocket_saas_on_submit_jobs'        => 'process_on_submit_jobs',
48				'rocket_saas_job_check_status'      => [ 'check_job_status', 10, 3 ],
49				'rocket_saas_clean_rows_time_event' => 'cron_clean_rows',
50				'cron_schedules'                    => 'add_interval',
51				'rocket_deactivation'               => 'on_deactivation',
52				'rocket_remove_saas_failed_jobs'    => 'cron_remove_failed_jobs',
53				'init'                              => [
54					[ 'schedule_clean_not_commonly_used_rows' ],
55					[ 'schedule_pending_jobs' ],
56					[ 'initialize_rucss_queue_runner' ],
57					[ 'schedule_removing_failed_jobs' ],
58					[ 'schedule_on_submit_jobs' ],
59				],
60				'wp_rocket_upgrade'                 => [ 'unschedule_rucss_cron', 13, 2 ],
61			];
62		}
63	
64		/**
65		 * Schedules cron to clean not commonly used rows.
66		 *
67		 * @since 3.9
68		 *
69		 * @return void
70		 */
71		public function schedule_clean_not_commonly_used_rows() {
72			if ( ! $this->job_processor->is_allowed() ) {
73				if ( wp_next_scheduled( 'rocket_saas_clean_rows_time_event' ) ) {
74					wp_clear_scheduled_hook( 'rocket_saas_clean_rows_time_event' );
75				}
76				return;
77			}
78	
79			if ( wp_next_scheduled( 'rocket_saas_clean_rows_time_event' ) ) {
80				return;
81			}
82	
83			wp_schedule_event( time(), 'weekly', 'rocket_saas_clean_rows_time_event' );
84		}
85	
86		/**
87		 * Initialize the queue runner for our SaaS.
88		 *
89		 * @return void
90		 */
91		public function initialize_rucss_queue_runner() {
92			if ( ! $this->job_processor->is_allowed() ) {
93				return;
94			}
95	
96			RUCSSQueueRunner::instance()->init();
97		}
98	
99		/**
100		 * Process pending jobs with Cron iteration.
101		 *
102		 * @return void
103		 */
104		public function process_pending_jobs() {
105			$this->job_processor->process_pending_jobs();
106		}
107	
108		/**
109		 * Process on submit jobs with Cron iteration.
110		 *
111		 * @return void
112		 */
113		public function process_on_submit_jobs() {
114			$this->job_processor->process_on_submit_jobs();
115		}
116	
117		/**
118		 * Cron callback for deleting old rows in both table databases.
119		 *
120		 * @since 3.9
121		 *
122		 * @return void
123		 */
124		public function cron_clean_rows() {
125			if ( ! $this->is_deletion_enabled() ) {
126				return;
127			}
128	
129			foreach ( $this->factories as $factory ) {
130				$manager = $factory->manager();
131				if ( ! $manager->is_allowed() || ! $manager->allow_clean_rows() ) {
132					continue;
133				}
134				$factory->table()->delete_old_rows();
135			}
136		}
137	
138		/**
139		 * Cron callback for removing failed jobs.
140		 *
141		 * @return void
142		 */
143		public function cron_remove_failed_jobs() {
144			$this->job_processor->clear_failed_urls();
145		}
146	
147		/**
148		 * Handle job status by DB url and is_mobile.
149		 *
150		 * @param string  $url Url from DB row.
151		 * @param boolean $is_mobile Is mobile from DB row.
152		 * @param string  $optimization_type The type of optimization request to send.
153		 *
154		 * @return void
155		 */
156		public function check_job_status( string $url, bool $is_mobile, string $optimization_type ) {
157			$this->job_processor->check_job_status( $url, $is_mobile, $optimization_type );
158		}
159	
160		/**
161		 * Adds new interval for SaaS pending jobs cron
162		 *
163		 * @since 3.11.3
164		 *
165		 * @param array[] $schedules An array of non-default cron schedule arrays.
166		 *
167		 * @return array
168		 */
169		public function add_interval( $schedules ) {
170			if ( ! $this->job_processor->is_allowed() ) {
171				return $schedules;
172			}
173	
174			/**
175			 * Filters the cron interval.
176			 *
177			 * @since 3.11
178			 *
179			 * @param int $interval Interval in seconds.
180			 */
181			$interval = rocket_apply_filter_and_deprecated(
182				'rocket_saas_pending_jobs_cron_interval',
183				[ 1 * rocket_get_constant( 'MINUTE_IN_SECONDS', 60 ) ],
184				'3.16',
185				'rocket_rucss_pending_jobs_cron_interval'
186			);
187	
188			$schedules['rocket_saas_pending_jobs'] = [
189				'interval' => $interval,
190				'display'  => esc_html__( 'WP Rocket process pending jobs', 'rocket' ),
191			];
192	
193			$default_interval = 3 * rocket_get_constant( 'DAY_IN_SECONDS', 86400 );
194			/**
195			 * Filters the cron interval for clearing failed jobs.
196			 *
197			 * @param int $interval Interval in seconds.
198			 */
199			$interval = rocket_apply_filter_and_deprecated(
200				'rocket_remove_saas_failed_jobs_cron_interval',
201				[ $default_interval ],
202				'3.16',
203				'rocket_remove_rucss_failed_jobs_cron_interval'
204			);
205			$interval = (bool) $interval ? $interval : $default_interval;
206	
207			$schedules['rocket_remove_saas_failed_jobs'] = [
208				'interval' => $interval,
209				'display'  => esc_html__( 'WP Rocket clear failed jobs', 'rocket' ),
210			];
211	
212			/**
213			 * Filters the cron interval for processing on submit jobs.
214			 *
215			 * @param int $interval Interval in seconds.
216			 */
217			$interval = (int) rocket_apply_filter_and_deprecated(
218				'rocket_remove_saas_on_submit_jobs_cron_interval',
219				[ 1 * rocket_get_constant( 'MINUTE_IN_SECONDS', 60 ) ],
220				'3.16',
221				'rocket_remove_rucss_on_submit_jobs_cron_interval'
222			);
223	
224			$schedules['rocket_saas_on_submit_jobs'] = [
225				'interval' => $interval,
226				'display'  => esc_html__( 'WP Rocket process on submit jobs', 'rocket' ),
227			];
228	
229			return $schedules;
230		}
231	
232		/**
233		 * Schedule on submit jobs.
234		 *
235		 * @return void
236		 */
237		public function schedule_on_submit_jobs() {
238			if (
239				! $this->job_processor->is_allowed()
240				&&
241				wp_next_scheduled( 'rocket_saas_on_submit_jobs' )
242			) {
243				wp_clear_scheduled_hook( 'rocket_saas_on_submit_jobs' );
244	
245				return;
246			}
247	
248			if ( ! $this->job_processor->is_allowed() ) {
249				return;
250			}
251	
252			if ( wp_next_scheduled( 'rocket_saas_on_submit_jobs' ) ) {
253				return;
254			}
255	
256			wp_schedule_event( time(), 'rocket_saas_on_submit_jobs', 'rocket_saas_on_submit_jobs' );
257		}
258	
259		/**
260		 * Schedules cron to get SaaS pendings jobs.
261		 *
262		 * @since 3.11.3
263		 *
264		 * @return void
265		 */
266		public function schedule_pending_jobs() {
267			if (
268				! $this->job_processor->is_allowed()
269				&&
270				wp_next_scheduled( 'rocket_saas_pending_jobs' )
271			) {
272				wp_clear_scheduled_hook( 'rocket_saas_pending_jobs' );
273	
274				return;
275			}
276	
277			if ( ! $this->job_processor->is_allowed() ) {
278				return;
279			}
280	
281			if ( wp_next_scheduled( 'rocket_saas_pending_jobs' ) ) {
282				return;
283			}
284	
285			wp_schedule_event( time(), 'rocket_saas_pending_jobs', 'rocket_saas_pending_jobs' );
286		}
287	
288		/**
289		 * Schedules cron to remove failed jobs.
290		 *
291		 * @return void
292		 */
293		public function schedule_removing_failed_jobs() {
294			if (
295				! $this->job_processor->is_allowed()
296				&&
297				wp_next_scheduled( 'rocket_remove_saas_failed_jobs' )
298			) {
299				wp_clear_scheduled_hook( 'rocket_remove_saas_failed_jobs' );
300	
301				return;
302			}
303	
304			if ( ! $this->job_processor->is_allowed() ) {
305				return;
306			}
307	
308			if ( wp_next_scheduled( 'rocket_remove_saas_failed_jobs' ) ) {
309				return;
310			}
311	
312			wp_schedule_event( time(), 'rocket_remove_saas_failed_jobs', 'rocket_remove_saas_failed_jobs' );
313		}
314	
315		/**
316		 * Clear schedule of SaaS CRONs on deactivation.
317		 *
318		 * @return void
319		 */
320		public function on_deactivation() {
321			wp_clear_scheduled_hook( 'action_scheduler_run_queue_rucss', [ 'WP Cron' ] );
322		}
323	
324		/**
325		 * Checks if the SaaS deletion is enabled.
326		 *
327		 * @return bool
328		 */
329		protected function is_deletion_enabled(): bool {
330			/**
331			 * Filters the enable SaaS job deletion value
332			 *
333			 * @param bool $delete_saas_jobs True to enable deletion, false otherwise.
334			 */
335			return (bool) rocket_apply_filter_and_deprecated(
336				'rocket_saas_deletion_enabled',
337				[ true ],
338				'3.16',
339				'rocket_rucss_deletion_enabled'
340			);
341		}
342	
343		/**
344		 * Unschedule old rucss crons.
345		 *
346		 * @since 3.16
347		 *
348		 * @param string $new_version New plugin version.
349		 * @param string $old_version Previous plugin version.
350		 *
351		 * @return void
352		 */
353		public function unschedule_rucss_cron( $new_version, $old_version ) {
354			if ( version_compare( $old_version, '3.16', '>=' ) ) {
355				return;
356			}
357	
358			wp_clear_scheduled_hook( 'rocket_rucss_on_submit_jobs' );
359			wp_clear_scheduled_hook( 'rocket_rucss_pending_jobs' );
360			wp_clear_scheduled_hook( 'rocket_remove_rucss_failed_jobs' );
361			wp_clear_scheduled_hook( 'rocket_rucss_clean_rows_time_event' );
362		}
363	}
