1	<?php
2	
3	namespace WP_Rocket\Engine\Common\JobManager;
4	
5	use WP_Rocket\Engine\Common\Clock\WPRClock;
6	use WP_Rocket\Engine\Common\JobManager\Queue\Queue;
7	use WP_Rocket\Engine\Common\JobManager\Strategy\Factory\StrategyFactory;
8	use WP_Rocket\Engine\Common\Utils;
9	use WP_Rocket\Engine\Optimization\RUCSS\APIHandler\APIClient;
10	use WP_Rocket\Logger\LoggerAware;
11	use WP_Rocket\Logger\LoggerAwareInterface;
12	
13	class JobProcessor implements LoggerAwareInterface {
14		use LoggerAware;
15	
16		/**
17		 * Array of Factories.
18		 *
19		 * @var array
20		 */
21		private $factories;
22	
23		/**
24		 * Queue instance.
25		 *
26		 * @var Queue
27		 */
28		private $queue;
29	
30		/**
31		 * Retry Strategy Factory
32		 *
33		 * @var StrategyFactory
34		 */
35		protected $strategy_factory;
36	
37		/**
38		 * Clock instance.
39		 *
40		 * @var WPRClock
41		 */
42		protected $wpr_clock;
43	
44		/**
45		 * Instantiate the class.
46		 *
47		 * @param array           $factories Array of factories.
48		 * @param Queue           $queue Queue instance.
49		 * @param StrategyFactory $strategy_factory Strategy Factory.
50		 * @param WPRClock        $clock Clock object instance.
51		 */
52		public function __construct(
53			array $factories,
54			Queue $queue,
55			StrategyFactory $strategy_factory,
56			WPRClock $clock
57		) {
58			$this->factories        = $factories;
59			$this->queue            = $queue;
60			$this->strategy_factory = $strategy_factory;
61			$this->wpr_clock        = $clock;
62		}
63	
64		/**
65		 * Determine if action is allowed.
66		 *
67		 * @return boolean
68		 */
69		public function is_allowed(): bool {
70			if ( ! $this->factories ) {
71				return false;
72			}
73	
74			$is_allowed = false;
75			foreach ( $this->factories as $factory ) {
76				$is_allowed = $is_allowed || $factory->manager()->is_allowed();
77			}
78	
79			return $is_allowed;
80		}
81	
82		/**
83		 * Process pending jobs inside cron iteration.
84		 *
85		 * @return void
86		 */
87		public function process_pending_jobs() {
88			/**
89			 * Fires at the start of the process pending jobs.
90			 *
91			 * @param string $current_time Current time.
92			 */
93			rocket_do_action_and_deprecated(
94				'rocket_saas_process_pending_jobs_start',
95				[ $this->wpr_clock->current_time( 'mysql', true ) ],
96				'3.16',
97				'rocket_rucss_process_pending_jobs_start'
98			);
99	
100			if ( ! $this->is_allowed() ) {
101				return;
102			}
103	
104			// Get some items from the DB with status=pending & job_id isn't empty.
105	
106			/**
107			 * Filters the pending jobs count.
108			 *
109			 * @since 3.11
110			 *
111			 * @param int $rows Number of rows to grab with each CRON iteration.
112			 */
113			$rows = rocket_apply_filter_and_deprecated(
114				'rocket_saas_pending_jobs_cron_rows_count',
115				[ 100 ],
116				'3.16',
117				'rocket_rucss_pending_jobs_cron_rows_count'
118			);
119	
120			$pending_jobs = $this->get_jobs( $rows, 'pending' );
121	
122			if ( ! $pending_jobs ) {
123				return;
124			}
125	
126			foreach ( $pending_jobs as $row ) {
127				$current_time = $this->wpr_clock->current_time( 'timestamp', true );
128				if ( $row->next_retry_time < $current_time ) {
129					$optimization_type = $this->get_optimization_type( $row );
130					// Change status to in-progress.
131					$this->make_status_inprogress( $row->url, $row->is_mobile, $optimization_type );
132					$this->queue->add_job_status_check_async( $row->url, $row->is_mobile, $optimization_type );
133				}
134			}
135	
136			/**
137			 * Fires at the end of the process pending jobs.
138			 *
139			 * @param string $current_time Current time.
140			 */
141			rocket_do_action_and_deprecated(
142				'rocket_saas_process_pending_jobs_end',
143				[ $this->wpr_clock->current_time( 'mysql', true ) ],
144				'3.16',
145				'rocket_rucss_process_pending_jobs_end'
146			);
147		}
148	
149		/**
150		 * Check job status by DB row ID.
151		 *
152		 * @param string  $url Url from DB row.
153		 * @param boolean $is_mobile Is mobile from DB row.
154		 * @param string  $optimization_type The type of optimization request to send.
155		 *
156		 * @return void
157		 */
158		public function check_job_status( string $url, bool $is_mobile, string $optimization_type ) {
159			$row_details = $this->get_single_job( $url, $is_mobile, $optimization_type );
160			if ( ! is_object( $row_details ) ) {
161				// Nothing in DB, bailout.
162				return;
163			}
164	
165			$job_factory = $this->factories[ $optimization_type ] ?? $this->factories['rucss'];
166	
167			// Send the request to get the job status from SaaS.
168			$job_details = $job_factory->api()->get_queue_job_status( $row_details->job_id, $row_details->queue_name, Utils::is_home( $row_details->url ) );
169	
170			$job_factory->manager()->validate_and_fail( $job_details, $row_details, $optimization_type );
171	
172			if (
173				200 !== (int) $job_details['code']
174				&&
175				$job_factory->manager()->allow_retry_strategies()
176			) {
177				$this->logger::debug( 'Job status failed for url: ' . $row_details->url, $job_details );
178				$this->decide_strategy( $row_details, $job_details, $optimization_type );
179	
180				return;
181			}
182			/**
183			 * Unlock preload URL.
184			 *
185			 * @param string $url URL to unlock
186			 */
187			do_action( 'rocket_preload_unlock_url', $row_details->url );
188	
189			$job_factory->manager()->process( $job_details, $row_details, $optimization_type );
190	
191			/**
192			 * Fires after successfully Processing the SaaS jobs.
193			 *
194			 * @param string $current_time Current time.
195			 */
196			rocket_do_action_and_deprecated(
197				'rocket_saas_check_job_status_end',
198				[ $this->wpr_clock->current_time( 'mysql', true ) ],
199				'3.16',
200				'rocket_rucss_check_job_status_end'
201			);
202	
203			/**
204			 * Fires after successfully processing the SaaS jobs.
205			 *
206			 * @param string $url Optimized Url.
207			 * @param array  $job_details Result of the request to get the job status from SaaS.
208			 */
209			rocket_do_action_and_deprecated(
210				'rocket_saas_complete_job_status',
211				[ $row_details->url, $job_details ],
212				'3.16',
213				'rocket_rucss_complete_job_status'
214			);
215		}
216	
217		/**
218		 * Process on submit jobs.
219		 *
220		 * @return void
221		 */
222		public function process_on_submit_jobs() {
223			/**
224			 * Fires at the start of the process on submit jobs.
225			 *
226			 * @param string $current_time Current time.
227			 */
228			rocket_do_action_and_deprecated(
229				'rocket_saas_process_on_submit_jobs_start',
230				[ $this->wpr_clock->current_time( 'mysql', true ) ],
231				'3.16',
232				'rocket_rucss_process_on_submit_jobs_start'
233			);
234	
235			if ( ! $this->is_allowed() ) {
236				return;
237			}
238	
239			/**
240			 * Pending rows cont.
241			 *
242			 * @param int $count Number of rows.
243			 */
244			$pending_job = rocket_apply_filter_and_deprecated(
245				'rocket_saas_pending_jobs_cron_rows_count',
246				[ 100 ],
247				'3.16',
248				'rocket_rucss_pending_jobs_cron_rows_count'
249			);
250	
251			/**
252			 * Maximum processing rows.
253			 *
254			 * @param int $max Max processing rows.
255			 */
256			$max_pending_rows = (int) rocket_apply_filter_and_deprecated(
257				'rocket_saas_max_pending_jobs',
258				[ 3 * $pending_job, $pending_job ],
259				'3.16',
260				'rocket_rucss_max_pending_jobs'
261			);
262	
263			$rows = $this->get_jobs( $max_pending_rows, 'submit' );
264	
265			if ( ! $rows ) {
266				return;
267			}
268	
269			foreach ( $rows as $row ) {
270				$optimization_type = $this->get_optimization_type( $row );
271				$response          = $this->send_api( $row->url, (bool) $row->is_mobile, $optimization_type );
272				$job_factory       = $this->factories[ $optimization_type ] ?? $this->factories['rucss'];
273	
274				if ( ! $response || ! $job_factory->api()->validate_add_to_queue_response( $response ) ) {
275					$job_factory->manager()->validate_and_fail(
276						[
277							'status'  => 'failed',
278							'message' => 'To Submit request failed',
279						],
280						$row,
281						$optimization_type
282						);
283					continue;
284				}
285	
286				/**
287				 * Lock preload URL.
288				 *
289				 * @param string $url URL to lock
290				 */
291				do_action( 'rocket_preload_lock_url', $row->url );
292	
293				$job_factory->manager()->process_jobid(
294					$row->url,
295					$response,
296					(bool) $row->is_mobile,
297					$optimization_type
298				);
299			}
300	
301			/**
302			 * Fires at the end of the process pending jobs.
303			 *
304			 * @param string $current_time Current time.
305			 */
306			rocket_do_action_and_deprecated(
307				'rocket_saas_process_on_submit_jobs_end',
308				[ $this->wpr_clock->current_time( 'mysql', true ) ],
309				'3.16',
310				'rocket_rucss_process_on_submit_jobs_end'
311			);
312		}
313	
314		/**
315		 * Send the job to the API.
316		 *
317		 * @param string $url URL to work on.
318		 * @param bool   $is_mobile Is the page for mobile.
319		 * @param string $optimization_type The type of optimization request to send.
320		 * @param bool   $with_timeout Whether to use custom timeout for synchronous requests.
321		 * @return array|false
322		 */
323		public function send_api( string $url, bool $is_mobile, string $optimization_type, bool $with_timeout = false ) {
324			$config = [
325				'is_mobile' => $is_mobile,
326				'is_home'   => Utils::is_home( $url ),
327			];
328	
329			$config = array_merge( $config, $this->set_request_params( $optimization_type ) );
330	
331			$job_factory           = $this->factories[ $optimization_type ] ?? $this->factories['rucss'];
332			$api_args              = $with_timeout ? [ 'timeout' => 10 ] : [];
333			$add_to_queue_response = $job_factory->api()->add_to_queue( $url, $config, $api_args );
334	
