363		/**
364		 * Clear failed urls.
365		 *
366		 * @return void
367		 */
368		public function clear_failed_urls(): void {
369			/**
370			 * Delay before failed saas jobs are deleted.
371			 *
372			 * @param string $delay delay before failed saas jobs are deleted.
373			 */
374			$delay = (string) rocket_apply_filter_and_deprecated(
375				'rocket_delay_remove_saas_failed_jobs',
376				[ '3 days' ],
377				'3.16',
378				'rocket_delay_remove_rucss_failed_jobs'
379			);
380	
381			if ( '' === $delay || '0' === $delay ) {
382				$delay = '3 days';
383			}
384			$parts = explode( ' ', $delay );
385	
386			$value = 3;
387			$unit  = 'days';
388	
389			if ( count( $parts ) === 2 && $parts[0] >= 0 ) {
390				$value = (float) $parts[0];
391				$unit  = $parts[1];
392			}
393	
394			foreach ( $this->factories as $factory ) {
395				if ( $factory->manager()->is_allowed() ) {
396					$failed_urls = $factory->manager()->clear_failed_jobs( $value, $unit );
397	
398					$hook = 'rocket_' . $factory->manager()->get_optimization_type() . '_after_clearing_failed_url';
399	
400					/**
401					 * Fires after clearing failed urls.
402					 *
403					 * @param array $urls Failed urls.
404					 */
405					do_action( $hook, $failed_urls ); // phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals
406				}
407			}
408		}
