444		public function get_jobs( int $num_rows, string $type ): array {
445			$allowed_types = [ 'pending', 'submit' ];
446	
447			if ( ! in_array( $type, $allowed_types, true ) ) {
448				return [];
449			}
450	
451			$rows = [];
452	
453			foreach ( $this->factories as $factory ) {
454				if ( ! $factory->manager()->is_allowed() ) {
455					continue;
456				}
457				switch ( $type ) {
458					case 'pending':
459						$rows = array_merge( $rows, $factory->manager()->get_pending_jobs( $num_rows ) );
460						break;
461					case 'submit':
462						$rows = array_merge( $rows, $factory->manager()->get_on_submit_jobs( $num_rows ) );
463						break;
464				}
465			}
466	
467			if ( ! $rows ) {
468				return [];
469			}
470	
471			return $rows;
