16		use LoggerAware;
17		use CSSTrait;
18		use AbstractManager;
19	
20		/**
21		 * UsedCss Query instance.
22		 *
23		 * @var UsedCSS_Query
24		 */
25		protected $query;
26	
27		/**
28		 * Filesystem instance
29		 *
