31		 */
32		private $filesystem;
33	
34		/**
35		 * RUCSS Context.
36		 *
37		 * @var ContextInterface
38		 */
39		protected $context;
40	
41		/**
42		 * The type of optimization applied for the current job.
43		 *
44		 * @var string
45		 */
46		protected $optimization_type = 'rucss';
47	
48		/**
49		 * Check if manager can process.
50		 *
51		 * @var boolean
52		 */
53		protected $can_process = true;
54	
