59		 */
60		protected $options;
61	
62		/**
63		 * Instantiate the class.
64		 *
65		 * @param UsedCSS_Query    $query Usedcss Query instance.
66		 * @param Filesystem       $filesystem Filesystem instance.
67		 * @param ContextInterface $context RUCSS Context.
68		 * @param Options_Data     $options Options instance.
69		 */
70		public function __construct(
71			UsedCSS_Query $query,
72			Filesystem $filesystem,
73			ContextInterface $context,
74			Options_Data $options
75		) {
76			$this->query      = $query;
77			$this->filesystem = $filesystem;
78			$this->context    = $context;
79			$this->options    = $options;
80		}
