82		/**
83		 * Get pending jobs from db.
84		 *
85		 * @param integer $num_rows Number of rows to grab.
86		 * @return array
87		 */
88		public function get_pending_jobs( int $num_rows ): array {
89			$pending_jobs = $this->query->get_pending_jobs( $num_rows );
90	
91			if ( ! $pending_jobs ) {
92				$this->logger::debug( 'RUCSS: No pending jobs are there.' );
93	
94				return [];
95			}
96	
97			return $pending_jobs;
98		}
99	
100		/**
101		 * Validate SaaS response and fail job.
102		 *
103		 * @param array  $job_details Details related to the job..
104		 * @param object $row_details Details related to the row.
105		 * @param string $optimization_type The type of optimization applied for the current job.
106		 *
107		 * @return void
108		 */
109		public function validate_and_fail( array $job_details, $row_details, string $optimization_type ): void {
110			if ( 'all' !== $optimization_type && $this->optimization_type !== $optimization_type ) {
111				return;
112			}
113	
114			if ( ! empty( $job_details['status'] ) && 'failed' === $job_details['status'] ) {
115				$this->make_status_failed( $row_details->url, $row_details->is_mobile, '500', $job_details['message'] );
116				return;
117			}
118	
119			/**
120			 * Filters the rocket min rucss css result size.
121			 *
122			 * @since 3.13.3
123			 *
124			 * @param int $min_rucss_size min size.
125			 */
126			$min_rucss_size = wpm_apply_filters_typed( 'integer', 'rocket_min_rucss_size', 150 );
127	
128			if ( isset( $job_details['contents']['shakedCSS_size'] ) && intval( $job_details['contents']['shakedCSS_size'] ) < $min_rucss_size ) {
129				$message = 'RUCSS: shakedCSS size is less than ' . $min_rucss_size;
130				$this->logger::error( $message );
131				$this->make_status_failed( $row_details->url, $row_details->is_mobile, '500', $message );
132	
133				$this->can_process = false;
134			}
135		}
136	
137		/**
138		 * Process SaaS response.
139		 *
140		 * @param array  $job_details Details related to the job..
141		 * @param object $row_details Details related to the row.
142		 * @param string $optimization_type The type of optimization applied for the current job.
143		 *
144		 * @return void
145		 */
146		public function process( array $job_details, $row_details, string $optimization_type ): void {
147			if ( ! $this->is_allowed( $optimization_type ) || ! $this->can_process ) {
148				return;
149			}
150	
151			$css = $this->apply_font_display_swap( $job_details['contents']['shakedCSS'] );
152	
153			/**
154			 * RUCSS hash.
155			 *
156			 * @param string $hash RUCSS hash.
157			 * @param string $css RUCSS content.
158			 * @param UsedCSSRow $row_details Job details.
159			 */
160			$hash = (string) apply_filters( 'rocket_rucss_hash',  md5( $css ), $css, $row_details );
161	
162			if ( ! $this->filesystem->write_used_css( $hash, $css ) ) {
163				$message = 'RUCSS: Could not write used CSS to the filesystem: ' . $row_details->url;
164				$this->logger::error( $message );
165				$this->query->make_status_failed( $row_details->url, $row_details->is_mobile, '', $job_details['message'] );
166	
167				return;
168			}
169	
170			$this->query->make_status_completed( $row_details->url, $row_details->is_mobile, $hash );
171		}
172	
173		/**
174		 * Set the request parameter to be sent to the SaaS
175		 *
176		 * @return array
177		 */
178		public function set_request_param(): array {
179			/**
180			 * Filters the RUCSS safelist
181			 *
182			 * @since 3.11
183			 *
184			 * @param array $safelist Array of safelist values.
185			 */
186			$safelist = apply_filters( 'rocket_rucss_safelist', $this->options->get( 'remove_unused_css_safelist', [] ) );
187	
188			/**
189			 * Filters the styles attributes to be skipped (blocked) by RUCSS.
190			 *
191			 * @since 3.14
192			 *
193			 * @param array $skipped_attr Array of safelist values.
194			 */
195			$skipped_attr = wpm_apply_filters_typed( 'array', 'rocket_rucss_skip_styles_with_attr', [] );
196	
197			return [
198				'rucss_safelist'    => $safelist,
199				'skip_attr'         => $skipped_attr,
200				'optimization_list' => [
201					'rucss',
202				],
203			];
204		}
205	
206		/**
207		 * Get the optimization type from the DB Row.
208		 *
209		 * @param object $row DB Row Object.
210		 * @return boolean|string
211		 */
212		public function get_optimization_type_from_row( $row ) {
213			if ( ! isset( $row->css ) ) {
214				return false;
215			}
216	
217			return $this->optimization_type;
218		}
219	
220		/**
221		 * Process Job ID by saving it into DB.
222		 *
223		 * @param string $url Row url.
224		 * @param array  $response API Response array.
225		 * @param bool   $is_mobile Is mobile or not.
226		 * @param string $optimization_type Optimization type.
227		 *
228		 * @return void
229		 */
230		public function process_jobid( string $url, array $response, bool $is_mobile, string $optimization_type ) {
231			$this->make_status_pending(
232				$url,
233				$response['contents']['jobId'],
234				$response['contents']['queueName'],
235				$is_mobile,
236				$optimization_type
237			);
238		}
239	}
