4	namespace WP_Rocket\Engine\Common\Queue;
5	
6	use WP_Rocket\Logger\Logger;
7	use ActionScheduler_Abstract_QueueRunner;
8	use ActionScheduler_Store;
9	use ActionScheduler_FatalErrorMonitor;
10	use ActionScheduler_AsyncRequest_QueueRunner;
11	
12	class RUCSSQueueRunner extends ActionScheduler_Abstract_QueueRunner {
13	
14		/**
15		 * Cron hook name.
16		 */
17		const WP_CRON_HOOK = 'action_scheduler_run_queue_rucss';
18	
19		/**
20		 * Cron schedule interval.
21		 */
22		const WP_CRON_SCHEDULE = 'every_minute';
23	
24		/**
25		 * Async Request Queue Runner instance.
26		 * We used the default one from AS.
27		 *
28		 * @var \ActionScheduler_AsyncRequest_QueueRunner Instance.
29		 */
30		protected $async_request;
31	
32		/**
33		 * Current runner instance.
34		 *
35		 * @var RUCSSQueueRunner Instance.
36		 */
37		private static $runner = null;
38	
39		/**
40		 * Current queue group.
41		 *
42		 * @var string
43		 */
44		private $group = 'rocket-rucss';
45	
46		/**
47		 * Get singleton instance.
48		 *
49		 * @return RUCSSQueueRunner Instance.
50		 */
51		public static function instance() {
52			if ( null === self::$runner ) {
53				self::$runner = new RUCSSQueueRunner();
54			}
55			return self::$runner;
56		}
57	
58		/**
59		 * ActionScheduler_QueueRunner constructor.
60		 *
61		 * @param ActionScheduler_Store|null                    $store Store Instance.
62		 * @param ActionScheduler_FatalErrorMonitor|null        $monitor Fatal Error monitor instance.
63		 * @param Cleaner|null                                  $cleaner Cleaner instance.
64		 * @param ActionScheduler_AsyncRequest_QueueRunner|null $async_request Async Request Queue Runner instance.
65		 */
66		public function __construct( ?ActionScheduler_Store $store = null, ?ActionScheduler_FatalErrorMonitor $monitor = null, ?Cleaner $cleaner = null, ?ActionScheduler_AsyncRequest_QueueRunner $async_request = null ) {
67			if ( is_null( $cleaner ) ) {
68				/**
69				 * Filters the clean batch size.
70				 *
71				 * @since 3.11.0.5
72				 *
73				 * @param int    $batch_size Batch size.
74				 * @param string $group The group name.
75				 *
76				 * @return int
77				 */
78				$batch_size = (int) apply_filters( 'rocket_action_scheduler_clean_batch_size', 100, $this->group );
79				$cleaner    = new Cleaner( $store, $batch_size, $this->group );
80			}
81	
82			parent::__construct( $store, $monitor, $cleaner );
83	
84			if ( is_null( $async_request ) ) {
85				$async_request = new \ActionScheduler_AsyncRequest_QueueRunner( $this->store );
86			}
87	
88			$this->async_request = $async_request;
89		}
90	
91		/**
92		 * Initialize the queue runner.
93		 */
94		public function init() {
95	
96			// phpcs:ignore WordPress.WP.CronInterval.CronSchedulesInterval
97			add_filter( 'cron_schedules', [ self::instance(), 'add_wp_cron_schedule' ] );
98	
99			// Check for and remove any WP Cron hook scheduled by Action Scheduler < 3.0.0, which didn't include the $context param.
100			$next_timestamp = wp_next_scheduled( self::WP_CRON_HOOK );
101			if ( $next_timestamp ) {
102				wp_unschedule_event( $next_timestamp, self::WP_CRON_HOOK );
103			}
104	
105			$cron_context = [ 'WP Cron' ];
106	
107			if ( ! wp_next_scheduled( self::WP_CRON_HOOK, $cron_context ) ) {
108				$schedule = apply_filters( 'rocket_action_scheduler_run_schedule', self::WP_CRON_SCHEDULE );
109				wp_schedule_event( time(), $schedule, self::WP_CRON_HOOK, $cron_context );
110			}
111	
112			// @phpstan-ignore-next-line Action callback returns int but should not return anything.
113			add_action( self::WP_CRON_HOOK, [ self::instance(), 'run' ] );
114			$this->hook_dispatch_async_request();
115		}
116	
117		/**
118		 * Hook check for dispatching an async request.
119		 */
120		public function hook_dispatch_async_request() {
121			add_action( 'shutdown', [ $this, 'maybe_dispatch_async_request' ] );
122		}
123	
124		/**
125		 * Unhook check for dispatching an async request.
126		 */
127		public function unhook_dispatch_async_request() {
128			remove_action( 'shutdown', [ $this, 'maybe_dispatch_async_request' ] );
129		}
130	
131		/**
132		 * Check if we should dispatch an async request to process actions.
133		 *
134		 * This method is attached to 'shutdown', so is called frequently. To avoid slowing down
135		 * the site, it mitigates the work performed in each request by:
136		 * 1. checking if it's in the admin context and then
137		 * 2. haven't run on the 'shutdown' hook within the lock time (60 seconds by default)
138		 * 3. haven't exceeded the number of allowed batches.
139		 *
140		 * The order of these checks is important, because they run from a check on a value:
141		 * 1. in memory - is_admin() maps to $GLOBALS or the WP_ADMIN constant
142		 * 2. in memory - transients use autoloaded options by default
143		 * 3. from a database query - has_maximum_concurrent_batches() run the query
144		 *    $this->store->get_claim_count() to find the current number of claims in the DB.
145		 *
146		 * If all of these conditions are met, then we request an async runner check whether it
147		 * should dispatch a request to process pending actions.
148		 */
149		public function maybe_dispatch_async_request() {
150			if ( is_admin() && ! \ActionScheduler::lock()->is_locked( 'async-request-runner' ) ) {
151				// Only start an async queue at most once every 60 seconds.
152				\ActionScheduler::lock()->set( 'async-request-runner' );
153				$this->async_request->maybe_dispatch();
154			}
155		}
156	
157		/**
158		 * Process actions in the queue. Attached to self::WP_CRON_HOOK i.e. 'action_scheduler_run_queue'
159		 *
160		 * The $context param of this method defaults to 'WP Cron', because prior to Action Scheduler 3.0.0
161		 * that was the only context in which this method was run, and the self::WP_CRON_HOOK hook had no context
162		 * passed along with it. New code calling this method directly, or by triggering the self::WP_CRON_HOOK,
163		 * should set a context as the first parameter. For an example of this, refer to the code seen in
164		 *
165		 * @see ActionScheduler_AsyncRequest_QueueRunner::handle()
166		 *
167		 * @param string $context Optional identifier for the context in which this action is being processed, e.g. 'WP CLI' or 'WP Cron'
168		 *        Generally, this should be capitalised and not localised as it's a proper noun.
169		 *
170		 * @return int
171		 */
172		public function run( $context = 'WP Cron' ) {
173			\ActionScheduler_Compatibility::raise_memory_limit();
174			\ActionScheduler_Compatibility::raise_time_limit( $this->get_time_limit() );
175			do_action( 'action_scheduler_before_process_queue' );// phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound
176			$this->run_cleanup();
177			$processed_actions = 0;
178			if ( false === $this->has_maximum_concurrent_batches() ) {
179				$batch_size = apply_filters( 'action_scheduler_queue_runner_batch_size', 25 );// phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound
180				do {
181					$processed_actions_in_batch = $this->do_batch( $batch_size, $context );
182					$processed_actions         += $processed_actions_in_batch;
183				} while ( $processed_actions_in_batch > 0 && ! $this->batch_limits_exceeded( $processed_actions ) ); // keep going until we run out of actions, time, or memory.
184			}
185	
186			do_action( 'action_scheduler_after_process_queue' );// phpcs:ignore WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedHooknameFound
187	
188			return $processed_actions;
189		}
190	
191		/**
192		 * Process a batch of actions pending in the queue.
193		 *
194		 * Actions are processed by claiming a set of pending actions then processing each one until either the batch
195		 * size is completed, or memory or time limits are reached, defined by @see $this->batch_limits_exceeded().
196		 *
197		 * @param int    $size The maximum number of actions to process in the batch.
198		 * @param string $context Optional identifier for the context in which this action is being processed, e.g. 'WP CLI' or 'WP Cron'
199		 *        Generally, this should be capitalised and not localised as it's a proper noun.
200		 * @return int The number of actions processed.
201		 */
202		protected function do_batch( $size = 100, $context = '' ) {
203			try {
204				$claim = $this->store->stake_claim( $size, null, [], $this->group );
205				$this->monitor->attach( $claim );
206				$processed_actions = 0;
207	
208				foreach ( $claim->get_actions() as $action_id ) {
209					// bail if we lost the claim.
210					if ( ! in_array( $action_id, $this->store->find_actions_by_claim_id( $claim->get_id() ), true ) ) {
211						break;
212					}
213					$this->process_action( $action_id, $context );
214					++$processed_actions;
215	
216					if ( $this->batch_limits_exceeded( $processed_actions ) ) {
217						break;
218					}
219				}
220				$this->store->release_claim( $claim );
221				$this->monitor->detach();
222				$this->clear_caches();
223				$this->reset_group();
224				return $processed_actions;
225			} catch ( \Exception $exception ) {
226				Logger::error( $exception->getMessage() );
227				$this->reset_group();
228				return 0;
229			}
230		}
231	
232		/**
233		 * Reset group in store's claim filter.
234		 *
235		 * @return void
236		 */
237		private function reset_group() {
238			if ( ! method_exists( $this->store, 'set_claim_filter' ) ) {
239				return;
240			}
241			$this->store->set_claim_filter( 'group', '' );
242		}
243	
244		/**
