26		/**
27		 * Run common checks.
28		 *
29		 * @param array $args Arguments to configure the checks.
30		 *
31		 * @return bool
32		 */
33		public function run_common_checks( array $args = [] ): bool {
34			if ( key_exists( 'do_not_optimize', $args ) && (bool) rocket_get_constant( 'DONOTROCKETOPTIMIZE' ) !== (bool) $args['do_not_optimize'] ) {
35				return false;
36			}
37	
38			if ( key_exists( 'bypass', $args ) && rocket_bypass() !== (bool) $args['bypass'] ) {
39				return false;
40			}
41	
42			if ( key_exists( 'option', $args ) && is_string( $args['option'] ) && ! (bool) $this->options->get( $args['option'], 0 ) ) {
43				return false;
44			}
45	
46			if ( key_exists( 'password_protected', $args ) && $this->is_password_protected() !== (bool) $args['password_protected'] ) {
47				return false;
48			}
49	
50			if ( key_exists( 'post_excluded', $args ) && is_string( $args['post_excluded'] ) && is_rocket_post_excluded_option( $args['post_excluded'] ) ) {
51				return false;
52			}
53	
54			// Bailout if user is logged in.
55			if ( key_exists( 'logged_in', $args ) && is_user_logged_in() !== (bool) $args['logged_in'] ) {
56				return false;
57			}
58	
59			return true;
60		}

